"""Runtime scanning of collection folders under the theme's roots."""

from __future__ import annotations

import logging
import re
from dataclasses import dataclass
from pathlib import Path

from .model import IMAGE_SUFFIXES, Theme

LOGGER = logging.getLogger(__name__)

# Blurred overview variants live next to the crisp image. They are generated by
# hand for the repository wallpapers and must never enter the random pool.
BLURRED_RE = re.compile(r"_blurred\.[^.]+$", re.IGNORECASE)


@dataclass(frozen=True)
class Library:
    files: dict[str, tuple[Path, ...]]
    unknown_dirs: tuple[Path, ...]
    missing_roots: tuple[Path, ...]

    def get(self, name: str) -> tuple[Path, ...]:
        return self.files.get(name, ())


def _images(folder: Path) -> list[Path]:
    try:
        entries = sorted(folder.iterdir(), key=lambda entry: entry.name)
    except OSError as exc:
        LOGGER.warning("cannot read wallpaper folder %s: %s", folder, exc)
        return []

    images = []
    for entry in entries:
        if entry.name.startswith("."):
            continue
        if BLURRED_RE.search(entry.name):
            continue
        if entry.suffix.lower() not in IMAGE_SUFFIXES:
            continue
        try:
            if not entry.is_file():
                continue
        except OSError:
            continue
        images.append(entry)
    return images


def scan(theme: Theme) -> Library:
    declared = {collection.name for collection in theme.collections}
    files: dict[str, list[Path]] = {name: [] for name in declared}
    seen: set[Path] = set()
    unknown: list[Path] = []
    missing: list[Path] = []

    for root in theme.roots:
        try:
            if not root.is_dir():
                missing.append(root)
                continue
            entries = sorted(root.iterdir(), key=lambda entry: entry.name)
        except OSError as exc:
            LOGGER.warning("cannot read wallpaper root %s: %s", root, exc)
            missing.append(root)
            continue

        for entry in entries:
            try:
                if not entry.is_dir():
                    continue
            except OSError:
                continue
            if entry.name not in declared:
                unknown.append(entry)
                continue
            for image in _images(entry):
                try:
                    key = image.resolve()
                except OSError:
                    key = image
                if key in seen:
                    continue
                seen.add(key)
                files[entry.name].append(image)

    return Library(
        files={name: tuple(paths) for name, paths in files.items()},
        unknown_dirs=tuple(unknown),
        missing_roots=tuple(missing),
    )
